UPDATE public.cards c
SET
  image_url=i.new_image_url,
  image_source_note='Scrydex public web image / refreshed 2026-08-29'
FROM incoming i
WHERE c.id=i.card_id
  AND c.image_url IS DISTINCT FROM i.new_image_url;

